<?php

namespace App\Models;

use App\Support\Lookups;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * `vehicles` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $VehicleID
 * @property string|null $VehicleName
 * @property string|null $VoucherName
 * @property string|null $VehicleBrand
 * @property int|null $VehicleYear
 * @property string|null $LicencePlate
 * @property Carbon|null $PurchaseDate
 * @property int|null $Passengers
 * @property string|null $VehicleType
 * @property string|null $VehicleLicence
 * @property int|null $VehicleTaxi
 * @property Carbon|null $SoldDate
 * @property int|null $Active
 * @property string|null $Tolls_Attiki
 * @property string|null $Tyres
 * @property string|null $Tolls_NeaOdos
 * @property string|null $Tolls_Group
 * @property string|null $AIA
 * @property Carbon|null $AIA_Expiry
 * @property int|null $order
 * @property string|null $Picture
 * @property string|null $flnm
 * @property string|null $FreeText
 */
class Vehicle extends Model
{
    protected $table = 'vehicles';

    protected $primaryKey = 'VehicleID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'VehicleID' => 'integer',
            'VehicleYear' => 'integer',
            'PurchaseDate' => 'date',
            'Passengers' => 'integer',
            'VehicleTaxi' => 'integer',
            'SoldDate' => 'date',
            'Active' => 'integer',
            'AIA_Expiry' => 'date',
            'order' => 'integer',
        ];
    }

    protected static function booted(): void
    {
        static::saved(fn () => Lookups::flush());
    }

    /** The picture is a blob; lists never load it. */
    protected $hidden = ['Picture'];

    public function logs(): HasMany
    {
        return $this->hasMany(VehiclesLog::class, 'VehicleID', 'VehicleID');
    }

    public function kilometres(): HasMany
    {
        return $this->hasMany(VehiclesKlm::class, 'VehicleID', 'VehicleID');
    }
}
